-- ----------------------------
-- Table structure for disk_store_bucket
-- ----------------------------

CREATE TABLE IF NOT EXISTS "disk_store_bucket" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(255) NOT NULL,
  "size" bigint DEFAULT NULL,
  "dir_count" integer DEFAULT NULL,
  "file_count" integer DEFAULT NULL,
  "crt_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "crt_user" varchar(32) NOT NULL,
  "crt_name" varchar(255) NOT NULL,
  "crt_host" varchar(255) DEFAULT NULL,
  "upd_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "upd_user" varchar(32) DEFAULT NULL,
  "upd_name" varchar(255) DEFAULT NULL,
  "upd_host" varchar(255) DEFAULT NULL,
  "deleted" boolean NOT NULL DEFAULT FALSE,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "disk_store_bucket" IS 'STORE-库';
COMMENT ON COLUMN "disk_store_bucket"."id" IS 'ID';
COMMENT ON COLUMN "disk_store_bucket"."name" IS '库名称';
COMMENT ON COLUMN "disk_store_bucket"."size" IS '总文件大小';
COMMENT ON COLUMN "disk_store_bucket"."dir_count" IS '目录数量';
COMMENT ON COLUMN "disk_store_bucket"."file_count" IS '文件数量';
COMMENT ON COLUMN "disk_store_bucket"."crt_time" IS '创建时间';
COMMENT ON COLUMN "disk_store_bucket"."crt_user" IS '创建用户ID';
COMMENT ON COLUMN "disk_store_bucket"."crt_name" IS '创建用户';
COMMENT ON COLUMN "disk_store_bucket"."crt_host" IS '创建IP';
COMMENT ON COLUMN "disk_store_bucket"."upd_time" IS '更新时间';
COMMENT ON COLUMN "disk_store_bucket"."upd_user" IS '更新用户ID';
COMMENT ON COLUMN "disk_store_bucket"."upd_name" IS '更新用户';
COMMENT ON COLUMN "disk_store_bucket"."upd_host" IS '更新IP';
COMMENT ON COLUMN "disk_store_bucket"."deleted" IS '是否删除';
DROP TRIGGER IF EXISTS "disk_store_bucket__upd_time" ON "disk_store_bucket";
CREATE TRIGGER "disk_store_bucket__upd_time" BEFORE UPDATE ON "disk_store_bucket" FOR EACH ROW EXECUTE FUNCTION fa_base_set_upd_time();

