COMMENT ON COLUMN "disk_store_bucket_user"."crt_user" IS '创建用户ID';
COMMENT ON COLUMN "disk_store_bucket_user"."crt_name" IS '创建用户';
COMMENT ON COLUMN "disk_store_bucket_user"."crt_host" IS '创建IP';
COMMENT ON COLUMN "disk_store_bucket_user"."upd_time" IS '更新时间';
COMMENT ON COLUMN "disk_store_bucket_user"."upd_user" IS '更新用户ID';
COMMENT ON COLUMN "disk_store_bucket_user"."upd_name" IS '更新用户';
COMMENT ON COLUMN "disk_store_bucket_user"."upd_host" IS '更新IP';
COMMENT ON COLUMN "disk_store_bucket_user"."deleted" IS '是否删除';
DROP TRIGGER IF EXISTS "disk_store_bucket_user__upd_time" ON "disk_store_bucket_user";
CREATE TRIGGER "disk_store_bucket_user__upd_time" BEFORE UPDATE ON "disk_store_bucket_user" FOR EACH ROW EXECUTE FUNCTION fa_base_set_upd_time();

-- ----------------------------
-- Table structure for disk_store_file
-- ----------------------------

CREATE TABLE IF NOT EXISTS "disk_store_file" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "bucket_id" integer NOT NULL,
  "name" varchar(255) NOT NULL,
  "parent_id" integer NOT NULL,
  "sort" integer DEFAULT NULL,
  "dir" boolean DEFAULT NULL,
  "size" integer DEFAULT NULL,
  "type" varchar(255) DEFAULT NULL,
  "file_id" varchar(64) DEFAULT NULL,
  "full_path" varchar(1000) DEFAULT NULL,
  "tags" jsonb DEFAULT NULL,
  "info" varchar(255) DEFAULT NULL,
  "delete_action" boolean DEFAULT NULL,
  "crt_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "crt_user" varchar(32) NOT NULL,
  "crt_name" varchar(255) NOT NULL,
  "crt_host" varchar(255) DEFAULT NULL,
  "upd_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "upd_user" varchar(32) DEFAULT NULL,
  "upd_name" varchar(255) DEFAULT NULL,
  "upd_host" varchar(255) DEFAULT NULL,
  "deleted" boolean NOT NULL DEFAULT FALSE,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "disk_store_file" IS 'STORE-文件夹';
COMMENT ON COLUMN "disk_store_file"."id" IS 'ID';
COMMENT ON COLUMN "disk_store_file"."bucket_id" IS '库ID';
COMMENT ON COLUMN "disk_store_file"."name" IS '文件夹名称';
COMMENT ON COLUMN "disk_store_file"."parent_id" IS '父级节点';
COMMENT ON COLUMN "disk_store_file"."sort" IS '排序ID';
COMMENT ON COLUMN "disk_store_file"."dir" IS '是否文件夹';
COMMENT ON COLUMN "disk_store_file"."size" IS '文件大小(目录下文件数量/KB)';
COMMENT ON COLUMN "disk_store_file"."type" IS '文件类型';
COMMENT ON COLUMN "disk_store_file"."file_id" IS '文件ID';
COMMENT ON COLUMN "disk_store_file"."full_path" IS '完整路径#dir#,#dir#';
COMMENT ON COLUMN "disk_store_file"."tags" IS '标签';
COMMENT ON COLUMN "disk_store_file"."info" IS '文件信息';
COMMENT ON COLUMN "disk_store_file"."delete_action" IS '是否有删除动作';
COMMENT ON COLUMN "disk_store_file"."crt_time" IS '创建时间';
COMMENT ON COLUMN "disk_store_file"."crt_user" IS '创建用户ID';
COMMENT ON COLUMN "disk_store_file"."crt_name" IS '创建用户';
COMMENT ON COLUMN "disk_store_file"."crt_host" IS '创建IP';
COMMENT ON COLUMN "disk_store_file"."upd_time" IS '更新时间';
COMMENT ON COLUMN "disk_store_file"."upd_user" IS '更新用户ID';
COMMENT ON COLUMN "disk_store_file"."upd_name" IS '更新用户';
COMMENT ON COLUMN "disk_store_file"."upd_host" IS '更新IP';
COMMENT ON COLUMN "disk_store_file"."deleted" IS '是否删除';
DROP TRIGGER IF EXISTS "disk_store_file__upd_time" ON "disk_store_file";
CREATE TRIGGER "disk_store_file__upd_time" BEFORE UPDATE ON "disk_store_file" FOR EACH ROW EXECUTE FUNCTION fa_base_set_upd_time();

